'use strict';

const Base = require('sdk-base');
const random = require('utility').random;
const sleep = require('mz-modules/sleep');

const DEFAULT_OPTIONS = {
  logger: console,
};

class ServerListManager extends Base {
  constructor(options = {}) {
    super(Object.assign({}, DEFAULT_OPTIONS, options));
  }

  get logger() {
    return this.options.logger;
  }

  get antvip() {
    return this.options.app.antvip;
  }

  get instanceId() {
    return this.options.app.config.instanceId;
  }

  get addressList() {
    if (this._healthyAddressList.length) {
      return this._healthyAddressList;
    }
    return this._allAddressList;
  }

  set addressList(val) {
    this._allAddressList = val;
    this._healthyAddressList = val.slice(0);
  }

  async init() {
    await this.updateConfigServers();
    this._doRefresh().catch(err => {
      this.emit('error', err);
    });
  }

  async _doRefresh() {
    if (!this.options.refreshEnable) return;

    while (!this._closed) {
      await sleep(this.options.refreshInterval);
      await this.updateConfigServers();
    }
  }

  async updateConfigServers() {
    const domain = `${this.instanceId}-DSR_CLOUD`;
    this.antvip.subscribe(domain, vipDomain => {
      if (vipDomain) {
        this.addressList = vipDomain.weightedRealServers.map(server => ({
          hostname: server.ip,
          port: server.effectiveHealthCheckPort || 9600,
        }));
        this.emit('config_servers_update', this.addressList);
      } else {
        this.emit('error', new Error(`[ConfigClient#ServerListMgr] get vipdomain failed, domain=${domain} is not exist`));
      }
    });

    await Promise.race([
      this.await('config_servers_update'),
      this.await('error'),
    ]);
  }

  /**
   * 连接断掉以后降低其权重
   * @method ServerListManager#adjustDownWeight
   * @param {String} hostname -
   * @return {void}
   */
  adjustDownWeight(hostname) {
    for (let i = 0, len = this._healthyAddressList.length; i < len; i++) {
      if (this._healthyAddressList[i].hostname === hostname) {
        this._healthyAddressList.splice(i, 1);
        break;
      }
    }
    if (!this._healthyAddressList.length) {
      this.emit('no_server_available');
    }
  }

  /**
   * 从 server 列表中任意选择一台
   * @method ServerListManager#randomSelect
   * @return {Address} 连接
   */
  randomSelect() {
    if (!this.addressList.length) {
      return null;
    }
    const index = random(this.addressList.length);
    return this.addressList[index];
  }

  /**
   * @method ServerListManager#reset
   * @return {void}
   */
  reset() {
    this._allAddressList = [];
    this._healthyAddressList = [];
    this._updateErrorTime = 0;
    this._lastSyncTime = 0;
  }

  /**
   * @method ServerListManager#close
   * @return {void}
   */
  close() {
    this._closed = true;
    this.reset();
    this.removeAllListeners();
  }
}

module.exports = ServerListManager;
